/* @socom-skeleton body GetByName__6CValveFPCc */
CValve* CValve::GetByName(const char* name)
{
	if (name)
	{
		auto it = m_list.begin();
		while (it != m_list.end())
		{
			CValve* current = *it;

			if (strcmp(current->m_name, name) == 0)
			{
				return current;
			}
			
			++it;
		}
	}

	return NULL;
}

